"""Check contributor declarations, not speculative AI-authorship detection."""
import json
import os
import re
from pathlib import Path

SECTIONS = (
    "Why & What Changed (Written in Your Own Words)",
    "Architectural & Invariant Impact",
    "AI Assistance Disclosure",
    "Verification Evidence",
    "Mandatory Human Attestation Checklist",
)
ATTESTATIONS = (
    "I wrote this Pull Request title and description myself in my own words (it was NOT written or auto-generated by AI).",
    "I have personally read, tested, and understood every line of code in this PR and take full responsibility for its correctness.",
    "I verified that all 48 historical v5/v5.1 hashes, 33 sealed v6 hashes, and Clean Architecture boundaries pass (the documentation validator and ./gradlew check apiCheck).",
)


def check(pr):
    if pr.get("user", {}).get("login") == "dependabot[bot]":
        return []  # CI and CODEOWNER approval still apply.
    raw = pr.get("body") or ""
    body = re.sub(r"<!--[\s\S]*?-->", "", raw)
    errors = []
    for section in SECTIONS:
        marker = "## " + section
        parts = body.split(marker)
        if len(parts) != 2:
            errors.append("Missing or duplicated section: " + section)
        elif not parts[1].split("\n## ", 1)[0].strip():
            errors.append("Empty section: " + section)
    for statement in ATTESTATIONS:
        if not re.search(r"(?im)^- \[x\] " + re.escape(statement) + r"\s*$", body):
            errors.append("Missing checked human attestation: " + statement)
    if re.search(r"(?im)^\s*-\s*\[ \]", body):
        errors.append("Unchecked checklist item")
    for marker in ("composedoc_forbidden_ai_summary_trigger", "composedoc_forbidden_ai_title_trigger", "@coderabbitai summary", "<!-- walkthrough_start -->", "<!-- summary by coderabbit.ai -->", "as an ai language model", "generated by chatgpt", "paste agent summary here"):
        if marker in (raw + "\n" + pr.get("title", "")).lower():
            errors.append("Unedited generated-summary marker: " + marker)
    if "@coderabbitai" in pr.get("title", "").lower():
        errors.append("Automatic PR title generation marker is prohibited")
    return errors


def main():
    event = json.loads(Path(os.environ["GITHUB_EVENT_PATH"]).read_text(encoding="utf-8"))
    errors = check(event["pull_request"])
    for error in errors:
        print(error)
    if errors:
        raise SystemExit(1)
    print("PASS contribution format and declarations; human authorship still requires human review")


if __name__ == "__main__":
    main()
